-- SG-Food: fuente transaccional sintética para PostgreSQL
-- Todos los datos son ficticios.
DROP SCHEMA IF EXISTS oltp_sgfood CASCADE;
CREATE SCHEMA oltp_sgfood;
SET search_path TO oltp_sgfood;

CREATE TABLE sucursal (id_sucursal INTEGER PRIMARY KEY, nombre VARCHAR(100) NOT NULL, ciudad VARCHAR(100) NOT NULL, departamento VARCHAR(100) NOT NULL);
CREATE TABLE categoria (id_categoria INTEGER PRIMARY KEY, nombre VARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE marca (id_marca INTEGER PRIMARY KEY, nombre VARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE producto (
 id_producto INTEGER PRIMARY KEY, sku VARCHAR(20) NOT NULL UNIQUE, nombre VARCHAR(150) NOT NULL,
 id_categoria INTEGER NOT NULL REFERENCES categoria(id_categoria), id_marca INTEGER NOT NULL REFERENCES marca(id_marca),
 unidad_medida VARCHAR(30) NOT NULL, costo_base NUMERIC(12,2) NOT NULL CHECK(costo_base>=0),
 precio_lista NUMERIC(12,2) NOT NULL CHECK(precio_lista>=0), activo BOOLEAN NOT NULL DEFAULT TRUE
);
CREATE TABLE cliente (
 id_cliente INTEGER PRIMARY KEY, nit VARCHAR(20) NOT NULL, nombre VARCHAR(150) NOT NULL,
 tipo_cliente VARCHAR(40) NOT NULL, municipio VARCHAR(100), departamento VARCHAR(100), fecha_alta DATE NOT NULL
);
CREATE TABLE venta (
 id_venta BIGINT PRIMARY KEY, fecha DATE NOT NULL, id_cliente INTEGER NOT NULL REFERENCES cliente(id_cliente),
 id_sucursal INTEGER NOT NULL REFERENCES sucursal(id_sucursal), canal VARCHAR(30) NOT NULL,
 metodo_pago VARCHAR(30) NOT NULL, estado VARCHAR(20) NOT NULL
);
CREATE TABLE venta_detalle (
 id_detalle BIGINT PRIMARY KEY, id_venta BIGINT NOT NULL REFERENCES venta(id_venta),
 id_producto INTEGER NOT NULL REFERENCES producto(id_producto), cantidad INTEGER NOT NULL CHECK(cantidad>0),
 precio_unitario NUMERIC(12,2) NOT NULL CHECK(precio_unitario>=0),
 descuento NUMERIC(5,4) NOT NULL DEFAULT 0 CHECK(descuento>=0 AND descuento<=1),
 subtotal NUMERIC(14,2) NOT NULL CHECK(subtotal>=0)
);
CREATE INDEX idx_venta_fecha ON venta(fecha);
CREATE INDEX idx_venta_cliente ON venta(id_cliente);
CREATE INDEX idx_detalle_venta ON venta_detalle(id_venta);
CREATE INDEX idx_detalle_producto ON venta_detalle(id_producto);

